import hashlib,json,pathlib,sys
p=pathlib.Path(__file__).resolve().parent; rp=pathlib.Path(sys.argv[1]); raw=json.loads(rp.read_text()); t=raw.get('terminal') or {}; rel=t.get('release') or {}; attempts=rel.get('key_release_attempts') or {}; code=str(raw.get('alias_codes',[None])[0]); sequence=(attempts.get(code) or {}).get('attempts') or [{}]; a=sequence[0]
checks={'candidate_terminal_recorded':t.get('event')=='terminal','alias_codes_equal_nonzero':len(raw.get('alias_codes',[]))==2 and raw['alias_codes'][0]!=0 and raw['alias_codes'][0]==raw['alias_codes'][1],'specific_alias_refusal':"distinct resolved keycodes required for up_batch" in str(t.get('error')),'held_at_cleanup_entry':a.get('server_key_down_before') is True,'key_release_verified':rel.get('verified') is True and a.get('server_key_down_after') is False,'neutral_observer_keymap':raw.get('keymap_after') is False,'xvfb_clean_exit':raw.get('xvfb_exit')==0}
outcome='PASS_METHOD_SCOPED' if all(checks.values()) and t.get('status')=='failed' else ('STOP' if raw.get('status')=='STOP' else 'FAIL')
res={'schema':'issue59-a10-independent-audit-v2','outcome':outcome,'checks':checks,'scope_note':'Raw code shows two distinct alias requests; owner error proves both aliases resolved and were owned before uniqueness refusal. Owner release sample confirms code held on cleanup entry.','raw_sha256':hashlib.sha256(rp.read_bytes()).hexdigest()}
(p/'results/A10_AUDIT_V2.json').write_text(json.dumps(res,indent=2,sort_keys=True)+'\n'); print(json.dumps(res,sort_keys=True))
